    fails += removed(.@"uqshrnt", &.{ .{ .z = .{ .id = 2, .et = .s } }, .{ .z = .{ .id = 9, .et = .h } }, .{ .imm = 3 } }, "uqshrnt z2.s, z9.h, #3");
    fails += removed(.@"uqshrnt", &.{ .{ .z = .{ .id = 2, .et = .d } }, .{ .z = .{ .id = 9, .et = .s } }, .{ .imm = 3 } }, "uqshrnt z2.d, z9.s, #3");
    try std.testing.expectEqual(@as(u32, 0), fails);
}
